import React, { useState, useEffect } from 'react';

function WarehouseOrdersProduct() {
    //const { ordernr } = useParams();
    const [products, setProducts] = useState([]);
    const [ warehouseOrderProduct, setarehouseOrderProduct] = useState(null);

    let [search, setSearch] = useState("")
    let [sort, setSort] = useState("productname")
        
        function onSearchChange(e) {
            setSearch(e.target.value)
        }
    
        function onSortChange(e) {
            setSort(e.target.value)
        }
    
        function getSortedProductsData() {
            return products.filter((item) => {
                return item.productname.toLowerCase().includes(search.toLowerCase())
            }).sort((a, b) => {
                return (a[sort] + "").localeCompare(b[sort] + "")
            })
        }





    return (
        <>
            <h1>Warehouse order Product</h1>
        </>
  )

}

export default WarehouseOrdersProduct;
